// Turn each agent's answer into data. If an answer is missing or unreadable, say so in the note.
const problems = [];

function read(nodeName, label) {
  let raw;
  try {
    raw = $(nodeName).first().json.output;
  } catch (e) {
    problems.push(`${label} could not be read (no node named "${nodeName}").`);
    return {};
  }
  if (raw && typeof raw === 'object') return raw; // already structured data
  try {
    const text = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    return JSON.parse(text);
  } catch (e) {
    problems.push(`${label} returned an answer that could not be read.`);
    return {};
  }
}

const news = read('Related News agent', 'The news search');
const compare = read('US vs India agent', 'The US vs India comparison');
const history = read('Modern history agent', 'The history comparison');

const context = {
  articles: news.articles || [],
  comparison: compare.comparison || [],
  history: history.history || [],
};
const notes = [news.note, compare.note, history.note, ...problems].filter(Boolean);
if (notes.length) context.note = notes.join(' ');

return { json: { contextJson: JSON.stringify(context) } };

const raw = String($('Analyze document1').first().json.content.parts[0].text);

const topics = [];
let current = null;
for (const line of raw.split(/\r?\n/)) {
  const text = line.replace(/\*\*/g, '').trim();
  if (!text) continue;
  let m;
  if ((m = /^TOPIC:\s*(.+)$/i.exec(text))) {
    current = { title: m[1].trim(), bullets: [] };
    topics.push(current);
  } else if (current && (m = /^ANALOGY:\s*(.+)$/i.exec(text))) {
    current.analogy = m[1].trim();
  } else if (current && (m = /^[-•*]\s+(.+)$/.exec(text))) {
    current.bullets.push(m[1].trim());
  }
}

const kept = topics.filter((t) => t.bullets.length > 0).slice(0, 3);

return {
  json: {
    topics: kept.map((t) => t.title),
    topicList: kept.map((t, i) => `${i + 1}. ${t.title}`).join('\n'),
    notesJson: kept.length ? JSON.stringify({ topics: kept }) : JSON.stringify(raw),
  },
};
